// =============================================================
// Hermes Settlement v5.0 — SUPABASE-FIRST AUTONOMOUS LOADER
// Primary source of truth: Supabase tahigoqhuyxedhmeqhnp/daily_picks
// Secondary non-blocking backup: HermesPicks Google Sheet (optional)
// =============================================================
const now = new Date();
const nowMs = now.getTime();

function normKey(s) {
  return String(s || '')
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9+.\-\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function toEatDate(isoStr) {
  const d = isoStr ? new Date(isoStr) : now;
  const valid = !isNaN(d.getTime()) ? d : now;
  return valid.toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' });
}

function formatEatKickoff(isoStr) {
  if (!isoStr) return '';
  const d = new Date(isoStr);
  if (isNaN(d.getTime())) return String(isoStr);
  const dt = d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', timeZone: 'Africa/Dar_es_Salaam' });
  const tm = d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Africa/Dar_es_Salaam' });
  return `${dt} ${tm} EAT`;
}

// 1. Read PRIMARY picks from Supabase (Read Supabase Picks node)
const sbRows = [];
try {
  for (const it of $('Read Supabase Picks').all()) {
    const j = it.json;
    if (Array.isArray(j)) {
      for (const row of j) {
        if (row && row.match && row.pick) sbRows.push(row);
      }
    } else if (j && j.match && j.pick && !j.error) {
      sbRows.push(j);
    }
  }
} catch (e) {}

// 2. Read OPTIONAL BACKUP rows from Google Sheet ($input)
const sheetInputs = $input.all();
let sheetOnline = false;
const sheetRows = [];
for (const r of sheetInputs) {
  const row = r.json || {};
  if (row.error) continue;
  if (row.Match && row.Market) {
    sheetOnline = true;
    sheetRows.push(row);
  }
}

const marketRepairMap = {
  'netherlands win (2)': 'Germany vs Netherlands',
  'slovakia win (2)': 'Kazakhstan vs Slovakia',
  'sweden win (2)': 'Poland vs Sweden',
  'austria win (2)': 'Israel vs Austria'
};

// Index Sheet rows by (normMatch::normMarket) so Supabase picks inherit row_number for dual-sync
const sheetPendingLookup = new Map();
const sheetParsed = [];

for (const row of sheetRows) {
  const rowNum = Number(row.row_number) || null;
  const result = String(row.Result || '').trim().toUpperCase();
  const kickoffISO = String(row.KickoffISO || '').trim();
  const timestampISO = String(row.Timestamp || '').trim();
  const baseDateEat = toEatDate(kickoffISO || timestampISO);

  const leagueStr = String(row.League || '').trim();
  const marketStr = String(row.Market || '').trim();
  let matchStr = String(row.Match || '').trim();
  let needsRepair = false;

  const repairTarget = marketRepairMap[marketStr.toLowerCase()];
  if (repairTarget && matchStr !== repairTarget) {
    matchStr = repairTarget;
    needsRepair = true;
  }

  const isBasketball = /nba|ncaa|basket|🏀|euroleague|wnba/i.test(leagueStr) || /pts|spread|\sml\s/i.test(marketStr);
  const odds = parseFloat(row.Odds) || 0;
  const units = parseFloat(row.StakeUnits) || 0;

  const itemObj = {
    row_number: rowNum,
    timestamp: timestampISO,
    eventId: String(row.EventId || '').trim(),
    sport: isBasketball ? 'basketball' : 'soccer',
    league: leagueStr,
    match: matchStr,
    kickoff: String(row.Kickoff || '').trim(),
    kickoffISO,
    kickoffDate: baseDateEat,
    market: marketStr,
    odds,
    probPct: parseFloat(row.ModelProb) || 0,
    edgePct: parseFloat(row.EdgePct) || 0,
    confidence: String(row.Confidence || '').trim(),
    units,
    sheetResult: result,
    needsRepair,
    fromSupabase: false
  };
  sheetParsed.push(itemObj);

  const mk = `${normKey(matchStr)}::${normKey(marketStr)}`;
  if (!sheetPendingLookup.has(mk) || (result !== 'WIN' && result !== 'LOSS')) {
    sheetPendingLookup.set(mk, itemObj);
  }
}

const pendingMap = {};
const settledMap = {};
const supabaseSeenMM = new Set();

// 3. Process SUPABASE rows FIRST (Source of Truth)
for (const r of sbRows) {
  const matchStr = String(r.match || '').trim();
  const marketStr = String(r.pick || r.market || '').trim();
  if (!matchStr || !marketStr) continue;

  const kickoffISO = String(r.kickoff_time || r.created_at || '').trim();
  const baseDateEat = toEatDate(kickoffISO);
  const sportRaw = String(r.sport || '').toLowerCase();
  const leagueStr = String(r.league || '').trim();
  const isBasketball = sportRaw.includes('basket') || /nba|ncaa|basket|euroleague|wnba/i.test(leagueStr);

  const tierStr = String(r.tier || '').trim().toUpperCase();
  let confLabel = tierStr;
  if (tierStr.includes('STRONG')) confLabel = '🟢 STRONG';
  else if (tierStr.includes('MODERATE')) confLabel = '🟡 MODERATE';
  else if (tierStr.includes('RISKY')) confLabel = '🔴 RISKY';
  else confLabel = tierStr || '🟢 STRONG';

  const odds = parseFloat(r.odds) || 0;
  const units = parseFloat(r.units) || 1;
  const probPct = parseFloat(r.confidence) || 70;
  const edgePct = parseFloat(r.edge_pct) || 0;

  const mmKey = `${normKey(matchStr)}::${normKey(marketStr)}`;
  supabaseSeenMM.add(mmKey);
  const sheetMatch = sheetPendingLookup.get(mmKey) || null;

  const itemObj = {
    supabaseId: r.id || null,
    fromSupabase: true,
    row_number: sheetMatch ? sheetMatch.row_number : null,
    timestamp: (sheetMatch && sheetMatch.timestamp) || r.created_at || kickoffISO,
    eventId: String(r.event_id || (sheetMatch && sheetMatch.eventId) || '').trim(),
    sport: isBasketball ? 'basketball' : 'soccer',
    league: leagueStr || (isBasketball ? 'NBA' : 'Football'),
    match: matchStr,
    origMatch: matchStr,
    origPick: String(r.pick || marketStr),
    origKickoffTime: r.kickoff_time || null,
    origReasoning: r.reasoning || null,
    origStreamId: r.stream_id || null,
    origSlipCode: r.slip_code || null,
    origHomeForm: r.home_form || null,
    origAwayForm: r.away_form || null,
    origInjuryNote: r.injury_note || null,
    origTier: r.tier || null,
    origConfidenceNum: r.confidence ?? null,
    kickoff: (sheetMatch && sheetMatch.kickoff) || formatEatKickoff(kickoffISO),
    kickoffISO,
    kickoffDate: baseDateEat,
    market: marketStr,
    odds,
    probPct,
    edgePct,
    confidence: confLabel,
    units
  };

  const status = String(r.status || 'published').trim().toLowerCase();
  const res = String(r.result || '').trim().toLowerCase();
  const dedupKey = `${baseDateEat}::${mmKey}`;

  if (status === 'settled' && (res === 'won' || res === 'win' || res === 'lost' || res === 'loss')) {
    const isWin = res === 'won' || res === 'win';
    const payout = isWin ? +(units * odds).toFixed(2) : 0;
    const profit = (r.profit_units !== null && r.profit_units !== undefined && r.profit_units !== '')
      ? +Number(r.profit_units).toFixed(2)
      : +(payout - units).toFixed(2);
    const roi = units > 0 ? +((profit / units) * 100).toFixed(1) : 0;
    settledMap[dedupKey] = {
      ...itemObj,
      result: isWin ? 'WIN' : 'LOSS',
      payout,
      profit,
      roi,
      scoreText: String(r.score || 'FT').trim() || 'FT'
    };
  } else if (status === 'published' || !res || res === 'pending') {
    pendingMap[dedupKey] = itemObj;
  }
}

// 4. Merge any Google Sheet rows not already covered by Supabase (e.g. historical settled or Sheet-only picks)
for (const itemObj of sheetParsed) {
  const mmKey = `${normKey(itemObj.match)}::${normKey(itemObj.market)}`;
  const dedupKey = `${itemObj.kickoffDate}::${mmKey}`;
  const res = itemObj.sheetResult;

  if (!itemObj.needsRepair && (res === 'WIN' || res === 'LOSS')) {
    if (!settledMap[dedupKey] && !supabaseSeenMM.has(mmKey)) {
      const payout = res === 'WIN' ? +(itemObj.units * itemObj.odds).toFixed(2) : 0;
      const profit = +(payout - itemObj.units).toFixed(2);
      const roi = itemObj.units > 0 ? +((profit / itemObj.units) * 100).toFixed(1) : 0;
      settledMap[dedupKey] = { ...itemObj, result: res, payout, profit, roi, scoreText: 'FT' };
    }
  } else {
    // Only add Sheet-only pending row if Supabase doesn't already track this match+market
    if (!supabaseSeenMM.has(mmKey) && !pendingMap[dedupKey]) {
      pendingMap[dedupKey] = itemObj;
    }
  }
}

const pending = Object.values(pendingMap);
const existingSettled = Object.values(settledMap);

// 5. Build lean ESPN scoreboard fetch plan for pending picks
const soccerDates = new Set();
const basketDates = new Set();

function addDateWindow(setObj, isoStr) {
  const d = new Date(isoStr);
  if (isNaN(d.getTime())) return;
  for (const offsetDays of [-1, 0, 1]) {
    const dt = new Date(d.getTime() + offsetDays * 86400000);
    const ymd = dt.toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' }).replace(/-/g, '');
    setObj.add(ymd);
  }
}

for (const p of pending) {
  const ref = p.kickoffISO || p.timestamp;
  if (p.sport === 'basketball') addDateWindow(basketDates, ref);
  else addDateWindow(soccerDates, ref);
}

const yest = new Date(nowMs - 86400000).toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' }).replace(/-/g, '');
const SOCCER_LEAGUES = [
  'uefa.nations','bra.1','usa.1','eng.1','esp.1','ita.1','ger.1','fra.1',
  'uefa.champions','uefa.europa','fifa.worldq.uefa','ned.1','por.1','tur.1'
];
const BASKET_LEAGUES = ['nba', 'mens-college-basketball'];

const fetches = [];
for (const dateKey of soccerDates) {
  for (const slug of SOCCER_LEAGUES) {
    fetches.push({ skip: false, sport: 'soccer', slug, dateKey });
  }
}
for (const dateKey of basketDates) {
  for (const slug of BASKET_LEAGUES) {
    fetches.push({ skip: false, sport: 'basketball', slug, dateKey });
  }
}

// Keep 1 fast lightweight fetch if 0 pending so manual Ledger Status still builds cleanly without Telegram spam on cron
if (fetches.length === 0) {
  fetches.push({ skip: false, sport: 'basketball', slug: 'nba', dateKey: yest });
}

return fetches.map((f, idx) => ({
  json: {
    ...f,
    allPending: idx === 0 ? pending : [],
    existingSettled: idx === 0 ? existingSettled : [],
    sheetOnline: idx === 0 ? sheetOnline : false,
    supabaseCount: idx === 0 ? sbRows.length : 0
  }
}));

// =============================================================
// Grade PENDING picks against ESPN results + enrich existing settled picks with FT scores
// Deduplicates per (date + match + market) for accurate P&L reporting
// =============================================================
const items = $input.all();
const planItems = $('Filter Pending & Build Fetch Plan').all();
const allPending = (planItems[0] && planItems[0].json && planItems[0].json.allPending) || [];
const existingSettled = (planItems[0] && planItems[0].json && planItems[0].json.existingSettled) || [];

const scoreMap = {};
const nameMap = {};

function normName(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\b(fc|sc|cf|ac|afc|united|city|club|de|da|do)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

for (const item of items) {
  const events = (item.json && item.json.events) || [];
  for (const ev of events) {
    const comp = (ev.competitions && ev.competitions[0]) || {};
    const cs = comp.competitors || [];
    const h = cs.find(c => c.homeAway === 'home') || {};
    const a = cs.find(c => c.homeAway === 'away') || {};
    const home = (h.team && h.team.displayName) || 'Home';
    const away = (a.team && a.team.displayName) || 'Away';
    const hShort = (h.team && (h.team.shortDisplayName || h.team.name || h.team.abbreviation)) || home;
    const aShort = (a.team && (a.team.shortDisplayName || a.team.name || a.team.abbreviation)) || away;
    const hScore = parseInt(h.score || '0', 10);
    const aScore = parseInt(a.score || '0', 10);
    const completed = !!(ev.status && ev.status.type && ev.status.type.completed);
    const detail = (ev.status && ev.status.type && ev.status.type.detail) || '';

    const result = {
      home, away, hShort, aShort,
      homeScore: hScore, awayScore: aScore,
      totalGoals: hScore + aScore,
      completed, detail
    };
    if (ev.id) scoreMap[String(ev.id)] = result;
    const key = `${home} vs ${away}`.toLowerCase();
    if (!nameMap[key] || completed) nameMap[key] = result;
  }
}

function teamMatches(target, teamFull, teamShort) {
  const t = normName(target);
  const f = normName(teamFull);
  const sh = normName(teamShort);
  if (!t) return false;
  return f.includes(t) || t.includes(f) || (sh.length >= 3 && (t.includes(sh) || sh.includes(t)));
}

function findScore(p) {
  if (p.eventId && scoreMap[p.eventId]) return scoreMap[p.eventId];
  const key = String(p.match || '').toLowerCase();
  if (nameMap[key]) return nameMap[key];
  const parts = key.split(/\s+vs\s+|\s+@\s+/);
  if (parts.length === 2) {
    for (const k of Object.keys(nameMap)) {
      const cand = nameMap[k];
      if (
        (teamMatches(parts[0], cand.home, cand.hShort) && teamMatches(parts[1], cand.away, cand.aShort)) ||
        (teamMatches(parts[0], cand.away, cand.aShort) && teamMatches(parts[1], cand.home, cand.hShort))
      ) {
        return cand;
      }
    }
  }
  return null;
}

function evaluateMarket(marketStr, s) {
  const m = String(marketStr || '').toUpperCase().trim();

  const ouMatch = m.match(/(OVER|UNDER)\s*(\d+(?:\.\d+)?)/);
  if (ouMatch) {
    const side = ouMatch[1];
    const line = parseFloat(ouMatch[2]);
    if (side === 'OVER') return s.totalGoals > line;
    if (side === 'UNDER') return s.totalGoals < line;
  }

  const spMatch = m.match(/^(?:SPREAD\s+|HANDICAP\s+)?(.+?)\s+([+-]\d+(?:\.\d+)?)(?:\s*PTS)?$/);
  if (spMatch && !m.includes('WIN (')) {
    const teamPart = spMatch[1].replace(/^SPREAD\s+/i, '').trim();
    const hcap = parseFloat(spMatch[2]);
    if (teamMatches(teamPart, s.home, s.hShort)) return (s.homeScore + hcap) > s.awayScore;
    if (teamMatches(teamPart, s.away, s.aShort)) return (s.awayScore + hcap) > s.homeScore;
  }

  if (m.includes('DC 1X') || m.includes('DOUBLE CHANCE 1X') || m === '1X') return s.homeScore >= s.awayScore;
  if (m.includes('DC X2') || m.includes('DOUBLE CHANCE X2') || m === 'X2') return s.awayScore >= s.homeScore;
  if (m.includes('DC 12') || m === '12') return s.homeScore !== s.awayScore;

  if (m.includes('WIN (1)') || m.endsWith(' (1)') || m.includes('HOME ML')) return s.homeScore > s.awayScore;
  if (m.includes('WIN (2)') || m.endsWith(' (2)') || m.includes('AWAY ML')) return s.awayScore > s.homeScore;
  if (m.includes(' ML') || m.includes(' WIN')) {
    const cleanTeam = m.replace(/\b(ML|WIN|\(WIN\)|MONEYLINE)\b/g, '').trim();
    if (teamMatches(cleanTeam, s.home, s.hShort)) return s.homeScore > s.awayScore;
    if (teamMatches(cleanTeam, s.away, s.aShort)) return s.awayScore > s.homeScore;
  }
  if (m === 'DRAW' || m === 'X') return s.homeScore === s.awayScore;
  if (m.includes('BTTS YES') || m.includes('GG')) return s.homeScore > 0 && s.awayScore > 0;
  if (m.includes('BTTS NO') || m.includes('NG')) return s.homeScore === 0 || s.awayScore === 0;

  return null;
}

const newlyGraded = [];
const stillPending = [];
const pendingDedup = new Set();

for (const p of allPending) {
  const s = findScore(p);
  if (!s || !s.completed) {
    const pk = `${p.match}::${p.market}`;
    if (!pendingDedup.has(pk)) {
      pendingDedup.add(pk);
      stillPending.push(p);
    }
    continue;
  }

  const hit = evaluateMarket(p.market, s);
  if (hit === null) {
    stillPending.push({ ...p, note: 'unrecognized market: ' + p.market });
    continue;
  }

  const payout = hit ? +(p.units * p.odds).toFixed(2) : 0;
  const profit = +(payout - p.units).toFixed(2);
  const roi = p.units > 0 ? +((profit / p.units) * 100).toFixed(1) : 0;

  newlyGraded.push({
    ...p,
    scoreHome: s.homeScore,
    scoreAway: s.awayScore,
    scoreText: `${s.home} ${s.homeScore} - ${s.awayScore} ${s.away}`,
    result: hit ? 'WIN' : 'LOSS',
    payout,
    profit,
    roi
  });
}

// Combine existingSettled + newlyGraded (deduplicated per date + match + market) for full reporting
const masterSettledMap = {};
for (const item of [...existingSettled, ...newlyGraded]) {
  const s = findScore(item);
  const scoreText = (s && s.completed) ? `${s.home} ${s.homeScore} - ${s.awayScore} ${s.away}` : (item.scoreText || 'FT');
  const dk = `${item.kickoffDate}::${item.match.toLowerCase()}::${item.market.toLowerCase()}`;
  masterSettledMap[dk] = { ...item, scoreText };
}

const allSettledUnique = Object.values(masterSettledMap);
const byDate = {};
for (const g of allSettledUnique) {
  byDate[g.kickoffDate] = byDate[g.kickoffDate] || { wins: 0, losses: 0, staked: 0, returned: 0, picks: [] };
  const b = byDate[g.kickoffDate];
  if (g.result === 'WIN') b.wins++;
  else b.losses++;
  b.staked += g.units;
  b.returned += g.payout;
  b.picks.push(g);
}

return [{
  json: {
    graded: newlyGraded, // Only newly graded rows need Sheet update
    allSettledUnique,
    stillPending,
    byDate,
    totalNewlyGraded: newlyGraded.length,
    totalSettledUnique: allSettledUnique.length,
    totalPending: stillPending.length
  }
}];

// Only update Google Sheet for rows that actually have a valid numeric row_number (> 1)
const input = $input.first().json || {};
const graded = input.graded || [];
return graded
  .filter(g => Number.isFinite(Number(g.row_number)) && Number(g.row_number) > 1)
  .map(g => ({
    json: {
      row_number: Number(g.row_number),
      Timestamp: g.timestamp,
      Match: g.match,
      Result: g.result,
      Payout: g.payout,
      ROI: g.roi
    }
  }));

// =============================================================
// Build SEPARATE, Systematic Telegram Settlement Messages (v5.0 — Supabase-First):
// - Message 1 (ONLY if Football matches settled): ⚽ FOOTBALL RESULTS
// - Message 2 (ONLY if Basketball matches settled): 🏀 BASKETBALL RESULTS
// - Never spams on scheduled runs when 0 new games finished!
// =============================================================
const input = $('Grade vs Results').first().json || {};
const planMeta = ($('Filter Pending & Build Fetch Plan').first() || {}).json || {};
const sheetOnline = !!planMeta.sheetOnline;
const newlyGraded = input.graded || [];
const allSettled = input.allSettledUnique || [];
const stillPending = input.stillPending || [];

function esc(t) {
  return String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

let isManual = false;
try {
  const m = $('Manual Trigger').all();
  if (m && m.length > 0) isManual = true;
} catch (e) {}

if (newlyGraded.length === 0 && !isManual) {
  return [];
}

const now = new Date();
const ds = now.toLocaleDateString('sw-TZ', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Africa/Dar_es_Salaam' });
const ts = now.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Africa/Dar_es_Salaam' });
const BANKROLL_TZS = parseInt($env.HERMES_BANKROLL_TZS || '100000', 10);
const UNIT_TZS = Math.round(BANKROLL_TZS / 100);
const syncFooter = sheetOnline
  ? '🤖 mwijay.duckdns.org · Supabase + Sheet Synced'
  : '🤖 mwijay.duckdns.org · Supabase Autonomous (⚠️ Sheet backup offline)';

const newMap = {};
for (const g of newlyGraded) {
  const k = `${g.match.toLowerCase()}::${g.market.toLowerCase()}`;
  newMap[k] = g;
}
const newUnique = Object.values(newMap);

function buildSportMessage(sportKey, list, allSportSafe, sportPending) {
  const isBasket = sportKey === 'basketball';
  const icon = isBasket ? '🏀' : '⚽';
  const title = isBasket ? 'HERMES NBA BASKETBALL RESULTS' : 'HERMES FOOTBALL RESULTS';

  const wins = list.filter(p => p.result === 'WIN');
  const losses = list.filter(p => p.result === 'LOSS');
  const staked = list.reduce((a, b) => a + b.units, 0);
  const returned = list.reduce((a, b) => a + b.payout, 0);
  const profit = returned - staked;
  const roi = staked > 0 ? (profit / staked) * 100 : 0;
  const wr = list.length > 0 ? (wins.length / list.length) * 100 : 0;
  const tzsProfit = Math.round(profit * UNIT_TZS);

  let msg = `${icon} ${title}\n📅 ${ds} | ⏰ ${ts} EAT\n━━━━━━━━━━━━━━━━━━━━━━\n`;
  msg += `🎯 Matokeo Mapya: ${wins.length}W / ${losses.length}L (${wr.toFixed(1)}% WR)\n`;
  msg += `💰 Faida: ${profit >= 0 ? '+' : ''}${profit.toFixed(2)}u (${roi >= 0 ? '+' : ''}${roi.toFixed(1)}% ROI) | ${tzsProfit >= 0 ? '+TZS ' : '-TZS '}${Math.abs(tzsProfit).toLocaleString()} ${profit >= 0 ? '🟢' : '🔴'}\n`;

  if (wins.length > 0) {
    const best = [...wins].sort((x, y) => y.profit - x.profit)[0];
    msg += `🏆 BEST WIN: ${esc(best.match)} → ${esc(best.market)} @ ${best.odds.toFixed(2)} (+${best.profit.toFixed(2)}u) 🔥\n`;
  }
  if (losses.length > 0) {
    const worst = [...losses].sort((x, y) => x.profit - y.profit)[0];
    msg += `⚠️ LOSS: ${esc(worst.match)} → ${esc(worst.market)} (${esc(worst.scoreText)})\n`;
  } else if (list.length > 0) {
    msg += `🔥 CLEAN SWEEP — 100% USHINDI!\n`;
  }

  msg += `\n`;
  list.slice(0, 6).forEach((p, i) => {
    const em = p.result === 'WIN' ? '✅ WON' : '❌ LOST';
    const sign = p.profit >= 0 ? '+' : '';
    const tr = String(p.confidence || '').includes('STRONG') ? '🟢' : (String(p.confidence || '').includes('MODERATE') ? '🟡' : '🔴');
    msg += `${i + 1}. ${em} ${esc(p.match)} (${esc(p.scoreText)})\n` +
           `   📌 ${tr} ${esc(p.market)} @ ${p.odds.toFixed(2)} | ${p.units}u → ${sign}${p.profit.toFixed(2)}u\n`;
  });

  if (allSportSafe.length > 0) {
    const sw = allSportSafe.filter(p => p.result === 'WIN').length;
    const sl = allSportSafe.length - sw;
    const sst = allSportSafe.reduce((a, b) => a + b.units, 0);
    const sret = allSportSafe.reduce((a, b) => a + b.payout, 0);
    const spr = sret - sst;
    const sroi = sst > 0 ? (spr / sst) * 100 : 0;
    msg += `\n📈 Jumla ya Rekodi (${icon} 🟢/🟡 Pesa Halisi): ${sw}W/${sl}L (${((sw / allSportSafe.length) * 100).toFixed(1)}% WR) | ${spr >= 0 ? '+' : ''}${spr.toFixed(2)}u (${sroi >= 0 ? '+' : ''}${sroi.toFixed(1)}% ROI)\n`;
  }

  if (sportPending.length > 0) {
    msg += `⏳ Zinasubiri (${icon}): ${sportPending.length} picks\n`;
  }
  msg += syncFooter;
  if (msg.length > 3950) msg = msg.substring(0, 3947) + '...';
  return msg;
}

const outputs = [];
const fbNew = newUnique.filter(p => p.sport !== 'basketball');
const bbNew = newUnique.filter(p => p.sport === 'basketball');

const safeAll = allSettled.filter(g => !String(g.confidence || '').includes('RISKY') && !String(g.confidence || '').includes('🔴'));
const fbSafe = safeAll.filter(p => p.sport !== 'basketball');
const bbSafe = safeAll.filter(p => p.sport === 'basketball');
const fbPend = stillPending.filter(p => p.sport !== 'basketball');
const bbPend = stillPending.filter(p => p.sport === 'basketball');

if (fbNew.length > 0) {
  outputs.push({ json: { sport: 'football', settlementText: buildSportMessage('football', fbNew, fbSafe, fbPend) } });
}
if (bbNew.length > 0) {
  outputs.push({ json: { sport: 'basketball', settlementText: buildSportMessage('basketball', bbNew, bbSafe, bbPend) } });
}

if (outputs.length === 0 && isManual) {
  const mkStatus = (icon, name, safeArr, pendArr) => {
    const sw = safeArr.filter(p => p.result === 'WIN').length;
    const sl = safeArr.length - sw;
    const sst = safeArr.reduce((a, b) => a + b.units, 0);
    const sret = safeArr.reduce((a, b) => a + b.payout, 0);
    const spr = sret - sst;
    let s = `${icon} ${name} — LEDGER STATUS\n📅 ${ds} | ⏰ ${ts} EAT\n━━━━━━━━━━━━━━━━━━━━━━\n`;
    if (safeArr.length > 0) {
      s += `📈 Pesa Halisi (🟢/🟡): ${sw}W / ${sl}L (${((sw / safeArr.length) * 100).toFixed(1)}% WR) | Net: ${spr >= 0 ? '+' : ''}${spr.toFixed(2)}u\n`;
    }
    s += `⏳ Zinazosubiri kuchezwa: ${pendArr.length} picks\n`;
    pendArr.slice(0, 4).forEach((p, i) => {
      s += `${i + 1}. ${esc(p.match)} → ${esc(p.market)} @ ${p.odds} (${esc(p.kickoff)})\n`;
    });
    s += `\n${syncFooter}`;
    return s;
  };
  outputs.push({ json: { sport: 'football', settlementText: mkStatus('⚽', 'FOOTBALL', fbSafe, fbPend) } });
  outputs.push({ json: { sport: 'basketball', settlementText: mkStatus('🏀', 'NBA BASKETBALL', bbSafe, bbPend) } });
}

return outputs;

// Sync newly settled picks from Hermes Settlement v5.0 to Supabase tahigoqhuyxedhmeqhnp/daily_picks
// Preserves original stream_id, reasoning, forms, slip_code & exact (match, pick, kickoff_time) unique key!
const g = $('Grade vs Results').first().json || {};
const graded = g.graded || [];
if (!graded.length) return [];

const strip = (v) => String(v ?? '')
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

function slipCode(match, market) {
  const s = `${match}|${market}`.toLowerCase();
  let h = 2166136261;
  for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; }
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let out = '', n = h;
  for (let i = 0; i < 5; i++) { out += alphabet[n % alphabet.length]; n = Math.floor(n / alphabet.length); }
  return `NLY-${out}`;
}

const nowIso = new Date().toISOString();
const seen = new Set();
const out = [];

for (const sp of graded) {
  const conf = String(sp.confidence || '');
  if (conf.toUpperCase().includes('RISKY') && !sp.fromSupabase) continue;
  const res = String(sp.result || '').toUpperCase();
  if (res !== 'WIN' && res !== 'LOSS') continue;

  const m = sp.origMatch || strip(sp.match);
  const mk = sp.origPick || strip(sp.market);
  const kt = sp.origKickoffTime || sp.kickoffISO || sp.timestamp || nowIso;
  const key = `${m}|${mk}|${kt}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const odds = Math.round((Number(sp.odds) || 0) * 100) / 100;
  const units = Math.round((Number(sp.units) || 1) * 100) / 100;
  const profit = Math.round((res === 'WIN' ? (units * odds - units) : -units) * 100) / 100;
  const isBb = /nba|ncaa|basket/i.test(String(sp.league || '') + ' ' + String(sp.sport || ''));
  const scoreVal = String(sp.scoreText || (Number.isFinite(sp.scoreHome) ? `${sp.scoreHome} - ${sp.scoreAway}` : '')).trim();
  const baseReason = sp.origReasoning ? String(sp.origReasoning).trim() : `Settled · Final Score: ${scoreVal || 'FT'}`;

  out.push({
    json: {
      match: m,
      league: strip(sp.league) || (isBb ? 'NBA' : 'Football'),
      pick: mk,
      market: mk,
      odds,
      confidence: Math.max(0, Math.min(100, Math.round(Number(sp.origConfidenceNum ?? sp.probPct ?? 70)))),
      reasoning: baseReason,
      kickoff_time: kt,
      slip_code: sp.origSlipCode || slipCode(m, mk),
      sport: isBb ? 'basketball' : 'football',
      tier: sp.origTier || strip(conf) || 'STRONG',
      units,
      edge_pct: Math.round((Number(sp.edgePct || 0)) * 10) / 10,
      event_id: String(sp.eventId || ''),
      stream_id: sp.origStreamId || null,
      home_form: sp.origHomeForm || null,
      away_form: sp.origAwayForm || null,
      injury_note: sp.origInjuryNote || null,
      score: scoreVal || 'FT',
      profit_units: profit,
      settled_at: nowIso,
      status: 'settled',
      result: res === 'WIN' ? 'won' : 'lost',
      source: 'hermes-n8n'
    }
  });
}
return out;
